package com.corecs.cpu.algorithm;
import com.corecs.cpu.model.*; import java.util.*;
public class SrtfAlgorithm implements SchedulingAlgorithm { public SimulationResult simulate(List<ProcessSpec> input,int q){var ps=SchedulingSupport.sorted(input);var rem=new HashMap<String,Integer>();ps.forEach(p->rem.put(p.id(),p.burstTime()));var out=new ArrayList<GanttSegment>();int t=0,i=0,done=0;while(done<ps.size()){while(i<ps.size()&&ps.get(i).arrivalTime()<=t)i++;ProcessSpec best=null;for(var p:ps)if(p.arrivalTime()<=t&&rem.get(p.id())>0&&(best==null||rem.get(p.id())<rem.get(best.id())||(rem.get(p.id()).equals(rem.get(best.id()))&&p.arrivalTime()<best.arrivalTime())))best=p;if(best==null){int a=ps.get(i).arrivalTime();out.add(new GanttSegment("IDLE",t,a));t=a;continue;}out.add(new GanttSegment(best.id(),t,t+1));rem.put(best.id(),rem.get(best.id())-1);t++;if(rem.get(best.id())==0)done++;}return SchedulingSupport.finish(ps,out);} }
